export function resolveDwarfMaterialId(key){return Object.hasOwn(DWARF_MATERIALS,key)?key:LEGACY_MATERIAL_IDS[key]??null;}
export function toDwarfInventoryKey(id){if(!Object.hasOwn(DWARF_MATERIALS,id))return null;return Object.keys(LEGACY_MATERIAL_IDS).find(key=>LEGACY_MATERIAL_IDS[key]===id)??id;}
export function getDwarfMaterialPool(monsterId,nodeId){return DWARF_MATERIAL_SOURCE_POOLS[monsterId+'|'+nodeId]??null;}
const approvedMerchantPrices={'铁屑':4,'炉火晶':7,'灰根草':5,'誓约残片':10,'dwarf.blackvein_ore':3,'dwarf.rock_lizard_sinew':8};
export const DWARF_MATERIAL_REGISTRY=freeze(Object.fromEntries(Object.values(DWARF_MATERIALS).map(m=>{const key=toDwarfInventoryKey(m.id),price=approvedMerchantPrices[key]??null;return [key,{...m,origin:'矮人诸境 · 指定来源',catalogId:m.id,merchantAllowed:price!==null,merchantBasePrice:price,price}]})));
export const DWARF_MERCHANT_PRICE_CANDIDATE=freeze({'常见':3,'少见':8,'珍奇':18});
const probability=n=>Number.isFinite(n)&&n>=0&&n<=1;
export function validDwarfMaterialPool(pool){
 return !!pool&&getDwarfMaterialPool(pool.monsterId,pool.nodeId)===pool&&pool.channels.every(c=>probability(c.hitProbability)&&Number.isSafeInteger(c.quantity)&&c.quantity>=1&&c.entries.every(e=>{const m=DWARF_MATERIALS[e.materialId];return m&&!m.storyOnly&&m.sources.includes(pool.nodeId)&&probability(e.weight)&&Array.isArray(e.qualityWeights)&&e.qualityWeights.length===4&&e.qualityWeights.every(probability)&&Math.abs(e.qualityWeights.reduce((a,b)=>a+b,0)-1)<1e-8;})&&(!c.entries.length?c.hitProbability===0:Math.abs(c.entries.reduce((a,e)=>a+e.weight,0)-1)<1e-8));
}
// Caller supplies quality/luck policy and synchronous inventory acceptance. No global pools,
// invented fallback materials, direct state writes or independent follower rewards.
export function rollMonsterMaterials(s,e,unit,{random,rollQuality,owned,receive,luck=0}={}){
 const monsterId=unit?.definitionId??unit?.monsterId,nodeId=unit?.sourceInstanceId??e?.instanceId,pool=getDwarfMaterialPool(monsterId,nodeId);
 if(e?.contentVersion!=='dwarf-m2-v1'||unit?.origin==='summoned'||unit?.independentRewards===false||!validDwarfMaterialPool(pool)||typeof random!=='function'||typeof rollQuality!=='function'||typeof owned!=='function'||typeof receive!=='function'||!Number.isFinite(luck)||luck<0||luck>1000)return {ok:false,reason:'source',drops:[]};
 const drops=[];
 for(const c of pool.channels){
  if(!c.entries.length||random()>=lootOccurrenceProbability(c.hitProbability,luck))continue;
  let pick=random(),chosen=c.entries.at(-1);for(const row of c.entries){pick-=row.weight;if(pick<0){chosen=row;break;}}
  const m=DWARF_MATERIALS[chosen.materialId];
  for(let i=0;i<c.quantity;i++){
   if(m.uniqueHeld&&owned(s,m.id))break;
   const quality=m.uniqueHeld?3:rollQuality([...chosen.qualityWeights],luck,random);
   if(!Number.isInteger(quality)||quality<0||quality>3)throw new Error('Invalid material quality result');
   const row={materialId:m.id,material:toDwarfInventoryKey(m.id),quality,quantity:1,channel:c.channel,monsterId,nodeId};
   const received=receive(s,row);drops.push({...row,received});
  }
 }
 return {ok:true,drops};
}

